import java.io.InputStreamReader
import java.util.StringTokenizer
import java.util.ArrayDeque

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    var st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()

    st = StringTokenizer(br.readLine())
    val f = IntArray(n)
    for (i in 0 until n) {
        f[i] = st.nextToken().toInt()
    }

    val g = Array(n) { IntArray(0) }
    val gr = Array(n) { IntArray(0) }

    val tmpG = Array(n) { mutableListOf<Int>() }
    val tmpGR = Array(n) { mutableListOf<Int>() }

    repeat(m) {
        st = StringTokenizer(br.readLine())
        val a = st.nextToken().toInt() - 1
        val b = st.nextToken().toInt() - 1
        tmpG[a].add(b)
        tmpGR[b].add(a)
    }

    for (i in 0 until n) {
        g[i] = tmpG[i].toIntArray()
        gr[i] = tmpGR[i].toIntArray()
    }

    // Kosaraju to find SCCs
    val visited = BooleanArray(n)
    val order = IntArray(n)
    var orderPos = 0

    fun dfs1(v: Int) {
        visited[v] = true
        for (to in g[v]) {
            if (!visited[to]) dfs1(to)
        }
        order[orderPos++] = v
    }

    for (i in 0 until n) {
        if (!visited[i]) dfs1(i)
    }

    val comp = IntArray(n) { -1 }
    var compCnt = 0

    fun dfs2(v: Int, c: Int) {
        comp[v] = c
        for (to in gr[v]) {
            if (comp[to] == -1) dfs2(to, c)
        }
    }

    for (i in n - 1 downTo 0) {
        val v = order[i]
        if (comp[v] == -1) {
            dfs2(v, compCnt++)
        }
    }

    // Build condensation DAG
    val compG = Array(compCnt) { mutableSetOf<Int>() }
    val hasAssign = BooleanArray(compCnt)
    val hasUse = BooleanArray(compCnt)

    for (v in 0 until n) {
        val c = comp[v]
        if (f[v] == 1) hasAssign[c] = true
        if (f[v] == 2) hasUse[c] = true
        for (to in g[v]) {
            val ct = comp[to]
            if (c != ct) compG[c].add(ct)
        }
    }

    // Topological order of condensation DAG
    val indeg = IntArray(compCnt)
    for (c in 0 until compCnt) {
        for (to in compG[c]) indeg[to]++
    }

    val q = ArrayDeque<Int>()
    for (c in 0 until compCnt) {
        if (indeg[c] == 0) q.add(c)
    }

    val topo = IntArray(compCnt)
    var tp = 0
    while (q.isNotEmpty()) {
        val v = q.removeFirst()
        topo[tp++] = v
        for (to in compG[v]) {
            indeg[to]--
            if (indeg[to] == 0) q.add(to)
        }
    }

    // DP: can reach a use without passing another assign
    val good = BooleanArray(compCnt)
    for (i in compCnt - 1 downTo 0) {
        val c = topo[i]
        var gHere = hasUse[c]
        for (to in compG[c]) {
            if (!hasAssign[to] && good[to]) gHere = true
        }
        good[c] = gHere
    }

    val res = StringBuilder()
    for (v in 0 until n) {
        val c = comp[v]
        if (hasAssign[c] && good[c]) res.append("1\n") else res.append("0\n")
    }
    print(res.toString())
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import java.util.ArrayDeque

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    var st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()

    st = StringTokenizer(br.readLine())
    val f = IntArray(n)
    for (i in 0 until n) {
        f[i] = st.nextToken().toInt()
    }

    val g = Array(n) { IntArray(0) }
    val gr = Array(n) { IntArray(0) }
    val outDeg = IntArray(n)
    val inDeg = IntArray(n)

    val tmpG = Array(n) { mutableListOf<Int>() }
    val tmpGr = Array(n) { mutableListOf<Int>() }

    repeat(m) {
        st = StringTokenizer(br.readLine())
        val a = st.nextToken().toInt() - 1
        val b = st.nextToken().toInt() - 1
        tmpG[a].add(b)
        tmpGr[b].add(a)
        outDeg[a]++
        inDeg[b]++
    }

    for (i in 0 until n) {
        g[i] = tmpG[i].toIntArray()
        gr[i] = tmpGr[i].toIntArray()
    }

    // Topological order using Kahn
    val q = ArrayDeque<Int>()
    val topo = IntArray(n)
    var tSize = 0
    val inDegCopy = inDeg.clone()
    for (i in 0 until n) {
        if (inDegCopy[i] == 0) q.add(i)
    }
    while (q.isNotEmpty()) {
        val v = q.removeFirst()
        topo[tSize++] = v
        for (to in g[v]) {
            inDegCopy[to]--
            if (inDegCopy[to] == 0) q.add(to)
        }
    }

    // If not all nodes processed, graph has cycles; problem constraints allow arbitrary graph.
    // We'll process only reachable via DAG-like order; for cycles, we can still use this order.

    val canReachUse = BooleanArray(n)
    val canReachAssign = BooleanArray(n)

    // Process in reverse topological order for canReachUse
    for (i in tSize - 1 downTo 0) {
        val v = topo[i]
        var cu = (f[v] == 2)
        for (to in g[v]) {
            if (canReachUse[to]) {
                cu = true
                break
            }
        }
        canReachUse[v] = cu
    }

    // Process in forward topological order for canReachAssign
    for (i in 0 until tSize) {
        val v = topo[i]
        var ca = (f[v] == 1)
        for (from in gr[v]) {
            if (canReachAssign[from]) {
                ca = true
                break
            }
        }
        canReachAssign[v] = ca
    }

    // DP for "bad" paths (with assignment after v)
    val bad = BooleanArray(n)
    // reverse topological for bad
    for (i in tSize - 1 downTo 0) {
        val v = topo[i]
        var b = (f[v] == 1)
        for (to in g[v]) {
            if (bad[to]) {
                b = true
                break
            }
        }
        bad[v] = b
    }

    val res = IntArray(n)
    for (v in 0 until n) {
        res[v] = if (canReachAssign[v] && canReachUse[v] && !bad[v]) 1 else 0
    }

    val sb = StringBuilder()
    for (i in 0 until n) {
        sb.append(res[i]).append('\n')
    }
    print(sb.toString())
}

