        gr[i] = tmpGR[i].toIntArray()
    }

    // Kosaraju to find SCCs
    val visited = BooleanArray(n)
    val order = IntArray(n)
    var ordPtr = 0

    fun dfs1(v: Int) {
        visited[v] = true
        for (to in g[v]) if (!visited[to]) dfs1(to)
        order[ordPtr++] = v
    }

    for (i in 0 until n) if (!visited[i]) dfs1(i)

    val comp = IntArray(n)
    java.util.Arrays.fill(comp, -1)
    var compCnt = 0

    fun dfs2(v: Int, c: Int) {
        comp[v] = c
        for (to in gr[v]) if (comp[to] == -1) dfs2(to, c)
    }

    for (i in n - 1 downTo 0) {
        val v = order[i]
        if (comp[v] == -1) {
            dfs2(v, compCnt)
            compCnt++
        }
    }

    // Build condensation graph
    val compG = Array(compCnt) { mutableListOf<Int>() }
    val hasEdge = HashSet<Long>()
    for (v in 0 until n) {
        val cv = comp[v]
        for (to in g[v]) {
            val cu = comp[to]
            if (cv != cu) {
                val key = (cv.toLong() shl 32) or cu.toLong()
                if (hasEdge.add(key)) compG[cv].add(cu)
            }
