    }

    // DP on DAG: from assign components forward, but stop when another assign reached
    val interestingComp = BooleanArray(compCnt)
    val queue = ArrayDeque<Int>()

    for (c in 0 until compCnt) {
        if (assign[c]) {
            interestingComp[c] = true
            queue.add(c)
