        st = StringTokenizer(br.readLine())
        val a = st.nextToken().toInt() - 1
        val b = st.nextToken().toInt() - 1
        outList[a].add(b)
        revList[b].add(a)
    }
    for (i in 0 until n) {
        g[i] = outList[i].toIntArray()
        gr[i] = revList[i].toIntArray()
    }

