    val visited = BooleanArray(n)
    val order = IntArray(n)
    var ordPtr = 0

    fun dfs1(v: Int) {
        visited[v] = true
        for (to in g[v]) if (!visited[to]) dfs1(to)
        order[ordPtr++] = v
    }

    for (i in 0 until n) if (!visited[i]) dfs1(i)

    val comp = IntArray(n) { -1 }
    var compCnt = 0

    fun dfs2(v: Int, c: Int) {
        comp[v] = c
        for (to in gr[v]) if (comp[to] == -1) dfs2(to, c)
    }

    for (i in n - 1 downTo 0) {
        val v = order[i]
        if (comp[v] == -1) {
            dfs2(v, compCnt)
            compCnt++
        }
    }

    // Build condensation graph
    val compOut = Array(compCnt) { mutableSetOf<Int>() }
    val compIn = Array(compCnt) { mutableSetOf<Int>() }
    val compAssign = BooleanArray(compCnt)
    val compUse = BooleanArray(compCnt)

    for (v in 0 until n) {
        val c = comp[v]
        if (f[v] == 1) compAssign[c] = true
        if (f[v] == 2) compUse[c] = true
        for (to in g[v]) {
            val ct = comp[to]
            if (c != ct) {
                if (compOut[c].add(ct)) {
                    compIn[ct].add(c)
                }
            }
        }
    }

    // Topological order of condensation graph
    val indeg = IntArray(compCnt)
    for (c in 0 until compCnt) indeg[c] = compIn[c].size
    val q = ArrayDeque<Int>()
    for (c in 0 until compCnt) if (indeg[c] == 0) q.add(c)
    val topo = IntArray(compCnt)
    var tp = 0
    while (!q.isEmpty()) {
        val v = q.removeFirst()
        topo[tp++] = v
        for (to in compOut[v]) {
            indeg[to]--
            if (indeg[to] == 0) q.add(to)
        }
    }

    // DP forward: can reach a use without passing another assign
    val goodForward = BooleanArray(compCnt)
    // For each component, whether it has an assign reachable from it without another assign
    val canReachAssign = BooleanArray(compCnt)

    // First, mark components that themselves contain assign and use
    // We'll propagate from assign components forward until hitting another assign
    val q2 = ArrayDeque<Int>()
    val visitedComp = BooleanArray(compCnt)

    for (c in 0 until compCnt) {
        if (compAssign[c]) {
            q2.add(c)
            visitedComp[c] = true
            canReachAssign[c] = true
        }
    }

    while (!q2.isEmpty()) {
        val v = q2.removeFirst()
        for (to in compOut[v]) {
            if (compAssign[to]) continue
            if (!visitedComp[to]) {
                visitedComp[to] = true
                canReachAssign[to] = true
                q2.add(to)
            }
        }
    }

    // Now from components that canReachAssign and have use, propagate backward to mark goodForward
    val q3 = ArrayDeque<Int>()
    val visitedBack = BooleanArray(compCnt)
    for (c in 0 until compCnt) {
        if (canReachAssign[c] && compUse[c]) {
            goodForward[c] = true
            q3.add(c)
            visitedBack[c] = true
        }
    }
    while (!q3.isEmpty()) {
        val v = q3.removeFirst()
        for (from in compIn[v]) {
            if (!visitedBack[from]) {
                visitedBack[from] = true
                goodForward[from] = true
                q3.add(from)
            }
        }
    }

    // DP backward: can reach an assign from a use without another assign
    val canReachUse = BooleanArray(compCnt)
    val q4 = ArrayDeque<Int>()
    val visitedComp2 = BooleanArray(compCnt)

    for (c in 0 until compCnt) {
        if (compUse[c]) {
            q4.add(c)
            visitedComp2[c] = true
            canReachUse[c] = true
        }
    }

    while (!q4.isEmpty()) {
        val v = q4.removeFirst()
        for (from in compIn[v]) {
            if (compAssign[from]) continue
            if (!visitedComp2[from]) {
                visitedComp2[from] = true
                canReachUse[from] = true
                q4.add(from)
            }
        }
    }

    val goodBackward = BooleanArray(compCnt)
    val q5 = ArrayDeque<Int>()
    val visitedBack2 = BooleanArray(compCnt)
    for (c in 0 until compCnt) {
        if (canReachUse[c] && compAssign[c]) {
            goodBackward[c] = true
            q5.add(c)
            visitedBack2[c] = true
        }
    }
    while (!q5.isEmpty()) {
        val v = q5.removeFirst()
        for (to in compOut[v]) {
            if (!visitedBack2[to]) {
                visitedBack2[to] = true
                goodBackward[to] = true
                q5.add(to)
            }
        }
    }

    val res = IntArray(n)
    for (v in 0 until n) {
        val c = comp[v]
        res[v] = if (goodForward[c] && goodBackward[c]) 1 else 0
    }

    val sb = StringBuilder()
    for (i in 0 until n) {
        sb.append(res[i]).append('\n')
    }
    print(sb.toString())
}

