    // Kosaraju to find SCCs
    val order = IntArray(n)
    var orderPos = 0
    val used = BooleanArray(n)
    val stack = ArrayDeque<Int>()

    fun dfs1(v: Int) {
        stack.clear()
        stack.add(v)
        while (stack.isNotEmpty()) {
            val x = stack.removeLast()
            if (!used[x]) {
                used[x] = true
                stack.add(x.inv()) // marker
                for (to in g[x]) if (!used[to]) stack.add(to)
            } else if (x < 0) {
                val real = x.inv()
                order[orderPos++] = real
            }
        }
    }

    for (i in 0 until n) if (!used[i]) dfs1(i)

    val comp = IntArray(n)
    var compCnt = 0
    used.fill(false)

    fun dfs2(v: Int, c: Int) {
        stack.clear()
        stack.add(v)
        used[v] = true
        comp[v] = c
        while (stack.isNotEmpty()) {
            val x = stack.removeLast()
            for (to in gr[x]) {
                if (!used[to]) {
                    used[to] = true
                    comp[to] = c
                    stack.add(to)
                }
            }
        }
    }

    for (i in n - 1 downTo 0) {
        val v = order[i]
        if (!used[v]) {
            dfs2(v, compCnt++)
        }
    }

    // Build condensation DAG
    val dag = Array(compCnt) { IntArray(0) }
    val tempDag = Array(compCnt) { mutableSetOf<Int>() }
    for (v in 0 until n) {
        val cv = comp[v]
        for (to in g[v]) {
            val cu = comp[to]
            if (cv != cu) tempDag[cv].add(cu)
        }
    }
    for (i in 0 until compCnt) {
        dag[i] = tempDag[i].toIntArray()
    }

    // For each component, check if it contains an assign and a use
    val hasAssign = BooleanArray(compCnt)
    val hasUse = BooleanArray(compCnt)
    for (i in 0 until n) {
        if (f[i] == 1) hasAssign[comp[i]] = true
        if (f[i] == 2) hasUse[comp[i]] = true
    }

    // DP on DAG: canReachUse and canReachAssign
    val canReachUse = BooleanArray(compCnt)
    val canReachAssign = BooleanArray(compCnt)

    // Topological order of DAG via DFS on components
    val topo = IntArray(compCnt)
    var tpos = 0
    used.fill(false)
    fun dfsDag(v: Int) {
        used[v] = true
        for (to in dag[v]) if (!used[to]) dfsDag(to)
        topo[tpos++] = v
    }
    for (i in 0 until compCnt) if (!used[i]) dfsDag(i)

    // process in reverse topo for canReachUse and canReachAssign
    for (i in 0 until compCnt) {
        val c = topo[i]
        var cu = hasUse[c]
        var ca = hasAssign[c]
        for (to in dag[c]) {
            cu = cu or canReachUse[to]
            ca = ca or canReachAssign[to]
        }
        canReachUse[c] = cu
        canReachAssign[c] = ca
    }

    // Now determine interesting states
    val res = IntArray(n)
    for (v in 0 until n) {
        val c = comp[v]
        val interesting = canReachAssign[c] && canReachUse[c]
        res[v] = if (interesting) 1 else 0
    }

    val sb = StringBuilder()
    for (i in 0 until n) {
        sb.append(res[i]).append('\n')
    }
    print(sb.toString())
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import java.util.ArrayDeque

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    var st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()

    st = StringTokenizer(br.readLine())
    val f = IntArray(n)
    for (i in 0 until n) {
        f[i] = st.nextToken().toInt()
    }

    val g = Array(n) { IntArray(0) }
    val gr = Array(n) { IntArray(0) }
    val outTmp = Array(n) { mutableListOf<Int>() }
    val inTmp = Array(n) { mutableListOf<Int>() }

    repeat(m) {
        st = StringTokenizer(br.readLine())
        val a = st.nextToken().toInt() - 1
        val b = st.nextToken().toInt() - 1
        outTmp[a].add(b)
        inTmp[b].add(a)
    }

    for (i in 0 until n) {
        g[i] = outTmp[i].toIntArray()
        gr[i] = inTmp[i].toIntArray()
    }

    // Topological sort on reversed graph (gr)
    val indeg = IntArray(n)
    for (i in 0 until n) {
        for (v in gr[i]) indeg[v]++
    }
    val q = ArrayDeque<Int>()
    for (i in 0 until n) if (indeg[i] == 0) q.add(i)
    val topo = IntArray(n)
    var tIdx = 0
    while (q.isNotEmpty()) {
        val v = q.removeFirst()
        topo[tIdx++] = v
        for (to in gr[v]) {
            indeg[to]--
            if (indeg[to] == 0) q.add(to)
        }
    }

    val dp = IntArray(n)
    // process in topo order on reversed graph
    for (i in 0 until tIdx) {
        val v = topo[i]
        var best = if (f[v] == 1) 1 else 0
        for (to in gr[v]) {
            val cand = dp[to] + if (f[v] == 1) 1 else 0
            if (cand > best) best = cand
        }
        dp[v] = best
    }

    val ans = IntArray(n)
    for (i in 0 until n) {
        ans[i] = if (dp[i] > 0 && f[i] != 1) 1 else 0
    }

    val sb = StringBuilder()
    for (i in 0 until n) {
        sb.append(ans[i]).append('\n')
    }
    print(sb.toString())
}
